200	    /**
201	     * The derived identity key used for duplicate detection, formed as
202	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}.
203	     * The telephone and email are already stored in their normalized forms (E.164 and
204	     * lower-cased), so the key is a straight concatenation of the stored values. Two owners
205	     * are considered the same only when their whole identity keys are equal.
206	     */
207	    @Transient
208	    public String getIdentityKey() {
209	        String tel = this.telephone == null ? "" : this.telephone;
210	        String mail = this.email == null ? "" : this.email;
211	        String household = this.householdId == null ? "" : this.householdId;
212	        return tel + "|" + mail + "|" + household;
213	    }
