226	    public List<Pet> getPets() {
227	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
228	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
229	        return Collections.unmodifiableList(sortedPets);
230	    }
231	
232	    public void setPets(List<Pet> pets) {
233	        this.pets = new HashSet<>(pets);
234	    }
