237	        getPetsInternal().add(pet);
238	        pet.setOwner(this);
239	    }
240	
241	    /**
242	     * Return the Pet with the given name, or null if none found for this Owner.
243	     *
244	     * @param name to test
245	     * @return true if pet name is already in use
246	     */
247	    public Pet getPet(String name) {
248	        return getPet(name, false);
249	    }
250	
251	    /**
252	     * Return the Pet with the given name, or null if none found for this Owner.
253	     *
254	     * @param name to test
255	     * @return true if pet name is already in use
256	     */
257	    public Pet getPet(String name, boolean ignoreNew) {
258	        name = name.toLowerCase();
259	        for (Pet pet : getPetsInternal()) {
260	            if (!ignoreNew || !pet.isNew()) {
261	                String compName = pet.getName();
262	                compName = compName.toLowerCase();
263	                if (compName.equals(name)) {
264	                    return pet;
265	                }
266	            }
267	        }
268	        return null;
269	    }
270	
271	    public Pet getPet(Integer petId) {
272	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
273	    }
274	
275	    @Override
276	    public String toString() {
277	        return new ToStringCreator(this)
278	
279	            .append("id", this.getId())
280	            .append("new", this.isNew())
281	            .append("lastName", this.getLastName())
282	            .append("firstName", this.getFirstName())
283	            .append("address", this.address)
284	            .append("city", this.city)
285	            .append("telephone", this.telephone)
286	            .append("email", this.email)
287	            .toString();
288	    }
289	}
